return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb45_02]],["connectPoint"]=0,["name"]=[[密室]],["roomAudioRule"]=1,["permission"]=1,["enterable"]=1,["dsc"]=[[一间狭小的密室，左右两边的墙壁上点着油灯，正中放置一个灵位，前面一个小香炉中燃着三柱清香，果盘里摆放四季香果，看来常常会有人到此。]],["fullName"]=[[密室(fb45_01)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc44]],["unit1"]=[[npc43]],["canLeave"]=1,["roomAudio"]=[[huo]],["id"]=[[fb45_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb45_03]],["connectPoint"]=0,["name"]=[[暗道]],["permission"]=1,["left"]=[[fb45_01]],["enterable"]=1,["dsc"]=[[细长的暗道，每每间隔数米就有一盏烛火，左右两侧的墙壁上有很多凹凸不平的地方，黑暗中摸索起来像是一个个被刻上去的文字。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[暗道(fb45_02)]],["canLeave"]=1,["id"]=[[fb45_02]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[暗道]],["permission"]=1,["left"]=[[fb45_02]],["enterable"]=1,["dsc"]=[[细长的暗道，每每间隔数米就有一盏烛火，左右两侧的墙壁上有很多凹凸不平的地方，黑暗中摸索起来像是一个个被刻上去的文字。]],["fullName"]=[[暗道(fb45_03)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc40c]],["canLeave"]=1,["id"]=[[fb45_03]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb45_05]],["connectPoint"]=0,["name"]=[[书房]],["permission"]=1,["enterable"]=1,["dsc"]=[[很普通的书房，桌案两侧各有一个大瓷瓶，后放一排书架，罗列着各类书籍。角落还有一张罗汉床，搁置着一盘尚未下完的棋局。]],["fullName"]=[[书房(fb45_04)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc50c]],["canLeave"]=1,["id"]=[[fb45_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[帮主卧房]],["permission"]=1,["left"]=[[fb45_04]],["fullName"]=[[帮主卧房(fb45_05)]],["enterable"]=1,["dsc"]=[[进门是一道山水屏风，前面放置一口大瓷缸，缸内养着几尾不知名的鱼。入内室则可以看见书案、床榻、雕窗，颇有江南风韵，倒不像是江湖草莽所居之地。]],["down"]=[[fb45_06]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc45p]],["unit1"]=[[npc42a]],["canLeave"]=1,["id"]=[[fb45_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[花园]],["permission"]=1,["enterable"]=1,["up"]=[[fb45_05]],["dsc"]=[[花园用篱笆围成，间有一块太湖瘦石，状如雄狮猛虎正要下山巡视。周围数盆花卉草木围